**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <vector>
using namespace std;

int odwroc(int n) {
    int rev = 0;
    while (n > 0) {
        rev = rev * 10 + n % 10;
        n /= 10;
    }
    return rev;
}

bool czyPalindrom(int n) {
    return n == odwroc(n);
}

int main() {
    ifstream plik("dane.txt");
    int liczba;
    int ile = 0;
    vector<int> palindromy;

    cout << "a) Operacja odwroc i dodaj:" << endl;
    while (plik >> liczba) {
        int rev = odwroc(liczba);
        int suma = liczba + rev;
        bool pal = czyPalindrom(suma);
        cout << liczba << ": " << liczba << " + " << rev << " = " << suma
             << " -> palindrom ";
        if (pal) {
            cout << "TAK" << endl;
            ile++;
            palindromy.push_back(suma);
        } else {
            cout << "NIE" << endl;
        }
    }

    cout << endl << "b) Liczb tworzacych palindrom po jednej iteracji: " << ile << endl;

    cout << endl << "c) Uzyskane palindromy:";
    for (int p : palindromy) {
        cout << " " << p;
    }
    cout << endl;
    return 0;
}
```

**Wyjasnienie**: Odwracamy liczbe standardowa petla (mod/div). Suma oryginalu i odwrocenia daje kandydata na palindrom. Palindrom sprawdzamy porownujac go z jego odwroceniem. Funkcja `odwroc()` sluzy zarowno do obliczenia odwrocenia, jak i do testu palindromu.

